module parity_8bit (
    input [7:0] in,
    output out
);

    wire a1, b1, c1, d1;
    wire e1, f1, g1, h1;
    wire i1, j1, k1, l1;
    wire m1, n1, o1, p1;

    assign a1 = in[0] ^ in[1];
    assign b1 = in[2] ^ in[3];
    assign c1 = a1 ^ b1;
    assign d1 = in[4] ^ in[5];
    assign e1 = in[6] ^ in[7];
    assign f1 = d1 ^ e1;
    assign g1 = c1 ^ f1;
    assign h1 = in[1] ^ in[5];
    assign i1 = a1 ^ d1;
    assign j1 = g1 ^ h1;
    assign k1 = i1 ^ j1;
    assign l1 = g1 ^ e1;
    assign m1 = a1 ^ f1;
    assign n1 = j1 ^ c1;
    assign o1 = k1 ^ n1;
    assign p1 = l1 ^ o1;

    assign out = p1;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire n_val0_5;
    wire not_val0_4;
    wire and_1_out;
    wire and_2_out;
    wire and_3_out;
    wire and_4_out;
    wire or_1_out;
    wire or_2_out;

    // NOT Gate
    not_unlabeled(not_val0_4, n_val0_5, in[0]);

    // AND Gate: in[1] AND sel[0]
    and_unlabeled(and_1_out, in[1], sel[0]);

    // AND Gate: sel[0] AND sel[1]
    and_unlabeled(and_2_out, sel[0], sel[1]);

    // AND Gate: in[1] AND sel[1]
    and_unlabeled(and_3_out, sel[1], in[1]);

    // AND Gate: in[2] AND sel[0]
    and_unlabeled(and_4_out, sel[0], in[2]);

    // OR Gate: not_val0_4 and in[2]
    or_unlabeled(or_1_out, not_val0_4, in[2]);

    // OR Gate: or_2_out and in[3]
    or_unlabeled(or_2_out, in[3], sel[1]);

    // OR Gate: or_1_out and or_2_out
    or_unlabeled(out[0], or_1_out, or_2_out);     
endmodule

module majority (
    input a, b, c,
    output out
);
    and u1 (.a(b), .b(c));
    and u2 (.a(a), .b(c));
    and u3 (.a(a), .b(b));
    and u4 (.a(u1.y), .b(u2.y));
    and u5 (.a(u3.y), .b(u4.y));
    or  u6 (.a(u2.y), .b(u5.y));
    or  u7 (.a(u1.y), .b(u6.y));
    assign out = u7.y;
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
assign gray[0] = (~binary[1] | binary[3]);
assign gray[1] = binary[0];
assign gray[2] = (~binary[0] | ~binary[1]);
assign gray[3] = (~binary[0] | binary[1]);
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

bit a, b;
assign a = ~b[0];
bit a_0;
assign a_0 = b[0];
assign b = ~a;
assign a = a_0 ^ b[0] & b ^ b[0] & b;
assign a = b ^ a[0] ^ a[0] & b;
assign a = a ^ a[1] ^ a[1] & b;
assign a = b ^ a[1] ^ a[1] & b;
assign a = b & a[1] ^ a[1] & b;
assign a = a ^ a[3] ^ a[3] & b;
assign a = b ^ a[3] ^ a[3] & b;
assign a = a & a[3] & b ^ a[3] & b;
assign b = b & a;
assign a = b;
assign a = b & a ^ a[2] ^ a ^ a[2] & b ^ a & a[2] & b ^ a[2] & b;
assign a = a ^ a[3] ^ b ^ a & ~b;
assign a = a[3] ^ b & a;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

wire out_00;
wire out_01;
wire out_10;
wire out_11;
wire out_20;
wire out_21;
wire out_30;
wire out_31;
wire out_40;
wire out_41;
wire out_50;
wire out_51;
wire out_60;
wire out_61;

assign out_00 = (~in) & ~in;
assign out_01 = (~in) & in;
assign out_10 = in & (~in);
assign out_11 = in & in;

assign out_20 = out_00 | out_10;
assign out_21 = out_01 | out_11;

assign out_30 = out_20 & out_10;
assign out_31 = out_21 & out_11;

assign out_40 = (!out_30) | (!out_31);
assign out_41 = (!out_30) & (!out_31);

assign out_50 = (!out_40) | (!out_41);
assign out_51 = (!out_40) & (!out_41);

assign out_60 = (!out_50) | (!out_51);
assign out_61 = (!out_50) & (!out_51);

assign out[0] = out_00;
assign out[1] = out_10;
assign out[2] = out_20;
assign out[3] = out_30;

endmodule

