module fsm_3state (
    input clk, reset,
    output [1:0] state
);

assign s_0_q = DFF_s_0_q_inst.Q;
assign s_1_q = DFF_s_1_q_inst.Q;
assign s_0_q_rst = DFF_s_0_q_inst.R;
assign DFF_s_0_q_inst.clk = DFF_s_1_q_inst.clk;
assign DFF_s_0_q_inst.d = s_1_q ~& DFF_s_0_q_inst.rst;

assign s_1_q_rst = DFF_s_1_q_inst.R;
assign DFF_s_1_q_inst.clk = DFF_s_0_q_inst.clk;
assign DFF_s_1_q_inst.d = !DFF_s_0_q_inst.rst ~& DFF_s_1_q_inst.rst;
assign state = DFF_s_0_q_inst.rst | DFF_s_1_q_inst.rst;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    wire a, b, c, d, e, f, g;

    // Inverters and basic gates
    assign a = ~reset;
    assign b = ~(reset ^ clk);
    assign c = (~(b & a));
    assign d = (~(c & a));
    assign e = (~(a & b));

    // Modular Assignments for more complex logic
    assign f = ~(c & d);
    assign g = ~(e & f);

    // Final Logic
    assign light[0] = ~(g & ~(clk & a));
    assign light[1] = g;
    assign light[2] = ~(g | clk);

endmodule

