module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    wire din_0, din_1, din_2;
    wire ceppop_0, ceppop_1;

    assign din_0 = reset & coin_inserted & item_selected;
    assign din_1 = clk & reset & item_selected;
    assign din_2 = clk | coin_inserted | item_selected;

    assign ceppop_0 = clk | coin_inserted;
    assign ceppop_1 = clk | item_selected;

    reg rip0, rip1, rip2, ripq0, ripq1;

    always @(ceppop_1 or din_0 or din_1 or din_2) begin
        rip0 <= din_0;
        rip1 <= din_1;
        rip2 <= din_2;
        ripq0 <= rip0 when ceppop_0;
        ripq1 <= rip1;
    end

    always @(ceppop_0 or ceppop_1) begin
        ripq0 <= rip0 when ceppop_0;
        ripq1 <= rip1;
    end

    assign state[0] = ~ripq0 & ripq1;
    assign state[1] = ~ripq0 | ~ripq1;
endmodule

