module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] f1, f2, f3, f4;
    wire [3:0] s;

    // Level 1: Combination logic to generate f1 - f4
    assign f1[0] = ~(data_in[0] & KEY[0]);
    assign f1[1] = ~(data_in[1] & KEY[1]);
    assign f1[2] = ~(data_in[2] & KEY[2]);
    assign f1[3] = ~(data_in[3] & KEY[3]);
    assign f2[0] = data_in[0];
    assign f2[1] = data_in[1];
    assign f2[2] = data_in[2];
    assign f2[3] = data_in[3];
    assign f3[0] = ~(data_in[0] & KEY[1]);
    assign f3[1] = ~(data_in[1] & KEY[2]);
    assign f3[2] = ~(data_in[2] & KEY[3]);
    assign f3[3] = ~(data_in[3] & KEY[0]);
    assign f4[0] = data_in[0];
    assign f4[1] = data_in[1];
    assign f4[2] = data_in[2];
    assign f4[3] = data_in[3];

    // Level 2: XORing f1 - f4
    assign s[0] = f1[0] ^ f2[0];
    assign s[1] = f1[1] ^ f2[1];
    assign s[2] = f1[2] ^ f2[2];
    assign s[3] = f1[3] ^ f2[3];

    // Level 3: XORing f3 - s
    assign f1[0] = s[0] ^ f3[0];
    assign f1[1] = s[1] ^ f3[1];
    assign f1[2] = s[2] ^ f3[2];
    assign f1[3] = s[3] ^ f3[3];

    // Level 4: XORing f1 - f4
    assign f2[0] = f1[0] ^ f4[0];
    assign f2[1] = f1[1] ^ f4[1];
    assign f2[2] = f1[2] ^ f4[2];
    assign f2[3] = f1[3] ^ f4[3];

