module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire w1, w2, w3, w4, w5, w6;
    wire w7, w8, w9;
    wire w10, w11, w12, w13, w14, w15, w16;

    assign w1 = A[0];
    assign w2 = A[1];
    assign w3 = A[2];
    assign w4 = B[0];
    assign w5 = B[1];
    assign w6 = B[2];

    not g1(w1, w1);
    not g2(w2, w2);
    xor g3(w3, w1, w2);
    xor g4(w4, w1, w2);
    xor g5(w5, w3, w4);

    and g6(w6, w5, w3);
    and g7(w7, w6, w5);

    nand g8(w8, w3, w5);

    xor g9(w9, w7, w1);

    nand g10(w10, w8, w9);
    nand g11(w11, w12, w13);
    or g12(w12, w10, w11);
    and g13(w13, w12, w14);
    nand g14(w14, w13, w15);
    or g15(w15, w7, w14);
    nand g16(w16, w9, w15);
    xor g17(A_greater, w16, w2);

    not g18(w7, w7);

    xor g19(w9, w7, w2);

    nand g20(w10, w3, w19);
    nand g21(w11, w10, w2);
    or g22(w11, w10, w21);
    and g23(w13, w22, w14);
    nand g24(A_equal, w13, w15);

    xor g25(A_less, w1, w23);

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    wire [3:0] a, b, c;

    assign a = A;
    assign b = B;

    wire a0, a1, a2, a3;
    wire b0, b1, b2, b3;
    wire c0, c1, c2, c3;

    assign a0 = a[0];
    assign a1 = a[1];
    assign a2 = a[2];
    assign a3 = a[3];

    assign b0 = b[0];
    assign b1 = b[1];
    assign b2 = b[2];
    assign b3 = b[3];

    wire a_not_0, a_not_1, a_not_2, a_not_3;
    wire b_not_0, b_not_1, b_not_2, b_not_3;
    wire c_not_0, c_not_1, c_not_2, c_not_3;

    assign a_not_0 = ~a0;
    assign a_not_1 = ~a1;
    assign a_not_2 = ~a2;
    assign a_not_3 = ~a3;

    assign b_not_0 = ~b0;
    assign b_not_1 = ~b1;
    assign b_not_2 = ~b2;
    assign b_not_3 = ~b3;

    assign c_not_0 = ~c0;
    assign c_not_1 = ~c1;
    assign c_not_2 = ~c2;
    assign c_not_3 = ~c3;

    wire a_nand_0, a_nand_1, a_nand_2, a_nand_3;
    wire b_nand_0, b_nand_1, b_nand_2, b_nand_3;
    wire c_nand_0, c_nand_1, c_nand_2, c_nand_3;

    assign a_nand_0 = ~(a0 & b0);
    assign a_nand_1 = ~(a1 & b1);
    assign a_nand_2 = ~(a2 & b2);
    assign a_nand_3 = ~(a3 & b3);

    assign b_nand_0 = ~(b0 & a0);
    assign b_nand_1 = ~(b1 & a1);
    assign b_nand_2 = ~(b2 & a2);
    assign b_nand_3 = ~(b3 & a3);

    assign c_nand_0 = ~(c0 & a0);
    assign c_nand_1 = ~(c1 & a1);
    assign c_nand_2 = ~(c2 & a2);
    assign c_nand_3 = ~(c3 & a3);

    wire a_xor_0, a_xor_1, a_xor_2, a_xor_3;
    wire b_xor_0, b_xor_1, b_xor_2, b_xor_3;
    wire c_xor_0, c_xor_1, c_xor_2, c_xor_3;

    assign a_xor_0 = a0 ^ b0;
    assign a_xor_1 = a1 ^ b1;
    assign a_xor_2 = a2 ^ b2;
    assign a_xor_3 = a3 ^ b3;

    assign b_xor_0 = a0 ^ b0;
    assign b_xor_1 = a1 ^ b1;
    assign b_xor_2 = a2 ^ b2;
    assign b_xor_3 = a3 ^ b3;

    assign c_xor_0 = a0 ^ b0;
    assign c_xor_1 = a1 ^ b1;
    assign c_xor_2 = a2 ^ b2;
    assign c_xor_3 = a3 ^ b3;

    wire a_comb_0, a_comb_1, a_comb_2, a_comb_3;
    wire b_comb_0, b_comb_1, b_comb_2, b_comb_3;
    wire c_comb_0, c_comb_1, c_comb_2, c_comb_3;

    assign a_comb_0 = (a0 | b0);
    assign a_comb_1 = (a1 | b1);
    assign a_comb_2 = (a2 | b2);
    assign a_comb_3 = (a3 | b3);

    assign b_comb_0 = (a0 | b0);
    assign b_comb_1 = (a1 | b1);
    assign b_comb_2 = (a2 | b2);
    assign b_comb_3 = (a3 | b3);

    assign c_comb_0 = (a0 | b0);
    assign c_comb_1 = (a1 | b1);
    assign c_comb_2 = (a2 | b2);
    assign c_comb_3 = (a3 | b3);

    wire a_out_0, a_out_1, a_out_2, a_out_3;
    wire b_out_0, b_out_1, b_out_2, b_out_3;
    wire c_out_0, c_out_1, c_out_2, c_out_3;

    assign a_out_0 = a_nand_0;
    assign a_out_1 = a_nand_1;
    assign a_out_2 = a_nand_2;
    assign a_out_3 = a_nand_3;

    assign b_out_0 = b_nand_0;
    assign b_out_1 = b_nand_1;
    assign b_out_2 = b_nand_2;
    assign b_out_3 = b_nand_3;

    assign c_out_0 = c_nand_0;
    assign c_out_1 = c_nand_1;
    assign c_out_2 = c_nand_2;
    assign c_out_3 = c_nand_3;

    assign A_greater = a_out_0;
    assign A_equal = a_out_1;
    assign A_less = a_out_2;

endmodule

