module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;
    wire clk;
    wire flopD, flopCas, flopCap, flopD0, flopSel, flopS0, flopT, flopN0S0, flopAndNew;

    // Automatic clock generation
    always begin
        if (clk == 1b0) clk <= 1b0;
        else clk <= 1b1;
    end

    // The main D Flip-Flop and Flops
    always @(posedge clk) begin
        flopD <= ($and (&/#(flopCap)));
        flopC <= flopC;
        flopCap <= 1b0;
        flopD0 <= flopSel;
        flopSel <= flopD0 & flopS0;
        flopS0 <= 1b1;
        flopT <= ($and (&/#(1'b0)));
        flopN0S0 <= ($nor(flopN0S0, flopSel));
        flopAndNew <= ($and({flopN0S0, flopSel}));
        clk_div <= flopAndNew ? 1b0 : flopAndNew ? 1b1 : $nor({clk, rst_n});
    end

    // Share clk with #clk
    wire #clk;
    output #clk;
    reg #clk;

    // Assign output from flip-flops
    assign flopD0 = flopD;
    assign flopC = flopC;
    assign flopCap = flopC;
    assign flopD0 = flopSel;
    assign flopSel = flopD0 & flopS0;
    assign flopS0 = flopS0;
    assign flopT = flopT;
    assign flopN0S0 = flopN0S0;
    assign flopAndNew = flopAndNew;
    assign clk_div = clk_div;
endmodule

