module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;
  reg dff0, dff1, dff2;

  always @(clk)
    dff0 <= clk;

  always @(dff0, clk, rst)
    dff1 <= clk & ~rst;

  always @(dff1)
    dff2 <= ~dff1;

  assign out[3] = 0;
    assign out[2] = dff0;
    assign out[1] = dff2;
    assign out[0] = dff1;
endmodule

