module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg q_ppo0;
reg q_pp0;
reg q_pp1;

always @(q_ppo0 or IN or MATCH or q_pp0 or q_pp1 or RST) begin
    MATCH <= (MATCH or (!q_ppo0 and MATCH) or (CLK and MATCH));
end

always @(CLK or IN or RST or q_ppo0 or q_pp0 or q_pp1) begin
    q_ppo0 <= (RST or (!IN and !CLK and RST and !IN and !q_pp0) or (!IN and CLK and RST and !q_pp0) or (!q_pp0 and IN and !CLK and !RST and RST and MATCH));
end

always @(q_ppo0 or q_pp0 or RST or IN) begin
    q_pp0 <= (CLK or (!q_ppo0 and CLK and !q_pp0) or (!IN and !CLK and !RST and q_pp0) or (!IN and CLK and !RST and !q_pp0 and CLK));
end

always @(IN or RST or CLK or q_pp1) begin
    q_pp1 <= (IN or (!CLK and !RST and q_pp1) or (!q_pp0 and !IN and !CLK and q_pp0) or (!IN and !CLK and q_pp1) or (!IN and CLK and !q_pp0 and RST and CLK));
end
endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

wire out_of_1;
wire out_of_2;
wire r1;
wire r2;
wire r3;
wire or14;
wire lassort;

assign out_of_1 = (rst_n & ((d[0] | d[1]) ));
assign out_of_2 = (rst_n & d[0]);
assign r1 = out_of_1;

assign r2 = (out_of_1 | d[1]);

assign r3 = (clk & ((d[0] & d[2]) | (d[0] & d[3]) | (d[1] & d[2]) | (d[1] & d[3]) | (d[2] & d[3])));
assign or14 = (r1 | r2 | r3);
assign lassort = ((r3 | clk) & (r2 | r1));

assign valid_out = ((!r1) & or14);
assign dout = lassort;

endmodule

