module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     reg S_DFF_PN0.Q_outputs;
     reg S_DFF_PN0.Q_temp;
     reg S_DFF_PN0.Q_temp1;
     reg S_DFF_PN1.Q_outputs;

     assign S_DFF_PN1.R = ~clk;

     always @(posedge clk)
     begin
        if(!S_DFF_PN0.C)
        begin
            S_DFF_PN0.Q_outputs <= S_DFF_PN0.D;
        end
        else
        begin
            S_DFF_PN0.Q_outputs <= ~S_DFF_PN0.D;
        end
     end
     always @(posedge clk)
     begin
        if(!S_DFF_PN1.C)
        begin
            S_DFF_PN1.Q_outputs <= S_DFF_PN1.D;
        end
        else
        begin
            S_DFF_PN1.Q_outputs <= ~S_DFF_PN1.D;
        end
     end
     assign sequence_detected = S_DFF_PN0.Q_outputs;
endmodule
